), updated_existing AS (
  UPDATE public.products AS product
  SET slug = lower(trim(both '-' from regexp_replace(product.name, '[^a-zA-Z0-9]+', '-', 'g'))) || '-' || left(product.id::text, 12),
      price = source.price,
      product_condition = source.product_condition,
      specifications = product.specifications || source.specifications,
      updated_at = now()
  FROM import_rows AS source
  WHERE source.existing_name_alias IS NOT NULL
    AND product.category = source.category
    AND lower(coalesce(product.specifications->>'Brand', '')) = lower(source.specifications->>'Brand')
    AND lower(product.name) = lower(source.existing_name_alias)
  RETURNING product.category, product.name, 'updated'::text AS action
), inserted AS (
  INSERT INTO public.products (name, slug, category, product_condition, description, specifications, price, currency, active, stock)
  SELECT source.name,
         lower(trim(both '-' from regexp_replace(source.name, '[^a-zA-Z0-9]+', '-', 'g'))) || '-' || left(gen_random_uuid()::text, 12),
         source.category,
         source.product_condition,
         source.description,
         source.specifications,
         source.price,
         'GHS',
         true,
         null
  FROM import_rows AS source
  WHERE NOT EXISTS (
    SELECT 1 FROM public.products AS existing
    WHERE existing.category = source.category
      AND lower(coalesce(existing.specifications->>'Brand', '')) = lower(source.specifications->>'Brand')
      AND lower(existing.name) = lower(source.name)
  )
    AND NOT EXISTS (
    SELECT 1 FROM public.products AS existing
    WHERE source.existing_name_alias IS NOT NULL
      AND existing.category = source.category
      AND lower(coalesce(existing.specifications->>'Brand', '')) = lower(source.specifications->>'Brand')
      AND lower(existing.name) = lower(source.existing_name_alias)
  )
  RETURNING category, name, 'inserted'::text AS action
)
SELECT action, category, count(*) AS products
FROM (SELECT * FROM updated_existing UNION ALL SELECT * FROM inserted) AS import_result
GROUP BY action, category
ORDER BY action, category;
